#: The builder's composer row at its narrowest: the model pill (cut or whole, its width and title), and the agent
#: label before it, whose content must end before the image button starts.
MODEL_PILL = """() => { const panel = document.querySelector('[data-testid="assistant-panel"]');
  const b = panel && panel.querySelector('[aria-label="Model for this build"]');
  const s = b && b.querySelector('span');
  const attach = panel && panel.querySelector('[aria-label="Attach images"]');
  // The row's first child holds the agent label; the image button's own sibling is its hidden file input.
  const agent = attach && attach.parentElement.firstElementChild && attach.parentElement.firstElementChild.firstElementChild;
  const right = (el) => el ? Math.round(el.getBoundingClientRect().right) : null;
  return b && s ? {label: s.textContent.trim(), cut: s.scrollWidth > s.clientWidth + 1,
                   width: Math.round(b.getBoundingClientRect().width), title: b.getAttribute('title'),
                   agentRight: right(agent), attachLeft: attach ? Math.round(attach.getBoundingClientRect().left) : null,
                   agentName: agent ? (agent.getAttribute('aria-label') || agent.textContent.trim()) : null} : null; }"""


@check
async def check_builderchip(browser) -> str:
    """On a phone the builder's model pill shows its whole label, and the row's "Synapse AI" overlaps nothing.

    It was held at 200 px, then by the row: a phone read "Default (Claude Haik…" and, with the cap gone, still
    "Default (workspa…" at 155 px beside the panel's "Synapse AI" label, which ran over the image button (F1131's
    follow-up; Naveen 2026-10-28: free width, then the label as its mark only on a phone — the header names it). Its
    name stays for a screen reader, and the pill's title is its whole label.
    """
    ctx, page = await _assistant_page(browser, path="agents", width=(390, 844))
    try:
        await page.locator('[data-testid="assistant-open"]:visible').first.click()
        await page.locator('[data-testid="assistant-panel"] [aria-label="Model for this build"]').first.wait_for(timeout=10_000)
        await asyncio.sleep(0.6)
        pill = await page.evaluate(MODEL_PILL)
    finally:
        await ctx.close()
    if not pill:
        raise AssertionError("no model pill in the builder panel at 390 px")
    bad = []
    if pill["cut"]:
        bad.append(f"the model pill is cut at {pill['width']} px: {pill['label']!r}")
    if pill["title"] != pill["label"]:
        bad.append(f"the pill's title is {pill['title']!r}, not its label {pill['label']!r}")
    if pill["agentRight"] is None or pill["attachLeft"] is None or pill["agentRight"] > pill["attachLeft"]:
        bad.append(f"the agent label ends at {pill['agentRight']}, past the image button at {pill['attachLeft']}")
    if pill["agentName"] != ASSISTANT_NAME:
        bad.append(f"the agent label is named {pill['agentName']!r}, not {ASSISTANT_NAME!r}")
    if bad:
        raise AssertionError("; ".join(bad))
    return f"at 390 px the model pill is whole ({pill['width']} px, {pill['label']!r}) and the agent label clears the image button"


#: Chat's composer row on a phone: the agent picker (its name shown or not, its accessible name, where it ends), the
#: image button's left edge, and the builder's model pill when the tab is Synapse AI's.
CHAT_PICKER = """() => { const main = document.querySelector('main');
  const picker = main && main.querySelector('[aria-label^="Agents: "]');
  const name = picker && picker.querySelector('span[title]');
  const attach = main && main.querySelector('[aria-label="Attach images"]');
  const model = main && main.querySelector('[aria-label="Model for this build"]');
  const s = model && model.querySelector('span');
  return picker ? {label: picker.getAttribute('aria-label'), nameShown: !!name && name.getBoundingClientRect().width > 2,
                   right: Math.round(picker.getBoundingClientRect().right),
                   attachLeft: attach ? Math.round(attach.getBoundingClientRect().left) : null,
                   model: s ? {label: s.textContent.trim(), cut: s.scrollWidth > s.clientWidth + 1} : null} : null; }"""


@check
async def check_chatpicker(browser) -> str:
    """On a phone Chat's agent picker is its icon and arrow, so a Synapse AI tab's model pill shows its whole label.

    The picker's name took the row a Synapse AI chat shares with the model pill, which read "Default (gpt-oss-…" at
    390 px (F1171; Naveen 2026-10-29: icon + ▾ on a phone, the name under the tab's title already). The name stays
    the picker's accessible name and in the list it opens; a plain agent's tab shows the picker the same way.
    """
    bad, said = [], []
    for scene, path in (("Synapse AI's tab", "?assistant=new"), ("an agent's tab", "")):
        ctx, page = await _assistant_page(browser, path=path, width=(390, 844))
        try:
            await page.locator('main [aria-label^="Agents: "]').first.wait_for(timeout=15_000)
            if path:
                await page.locator('main [aria-label="Model for this build"]').first.wait_for(timeout=15_000)
            await asyncio.sleep(0.8)
            m = await page.evaluate(CHAT_PICKER)
        finally:
            await ctx.close()
        if not m:
            bad.append(f"{scene}: no agent picker at 390 px")
            continue
        if m["nameShown"]:
            bad.append(f"{scene}: the picker shows its name ({m['label']!r}) on a phone")
        if m["label"] in (None, "Agents: "):
            bad.append(f"{scene}: the picker has no accessible name ({m['label']!r})")
        if m["attachLeft"] is not None and m["right"] > m["attachLeft"]:
            bad.append(f"{scene}: the picker ends at {m['right']}, past the image button at {m['attachLeft']}")
        if path and (not m["model"] or m["model"]["cut"]):
            bad.append(f"{scene}: the model pill is cut: {m['model']}")
        said.append(f"{scene}: {m['label']!r}" + (f", model {m['model']['label']!r} whole" if path and m["model"] else ""))
    if bad:
        raise AssertionError("; ".join(bad))
    return "at 390 px the agent picker is its icon and arrow — " + "; ".join(said)


#: The builder panel on a phone: its box against the window, where its "Things to ask" end, and whose the bottom
#: corner is — with the panel's own computed box for a failure to say why.
PHONE_PANEL = """() => { const panel = document.querySelector('[data-testid="assistant-panel"]');
  if (!panel) return null;
  const r = (el) => { if (!el) return null; const b = el.getBoundingClientRect();
                      return {top: Math.round(b.top), bottom: Math.round(b.bottom)}; };
  const list = panel.querySelector('ul[aria-label="Things to ask"]');
  const corner = document.elementFromPoint(24, window.innerHeight - 20);
  const cs = getComputedStyle(panel);
  return {vh: window.innerHeight, panel: r(panel), list: r(list),
          cornerInPanel: !!(corner && corner.closest('[data-testid="assistant-panel"]')),
          corner: corner ? (corner.tagName + '.' + String(corner.className).slice(0, 60)) : null,
          style: {position: cs.position, top: cs.top, bottom: cs.bottom, height: cs.height}}; }"""


@check
async def check_builderphonepanel(browser) -> str:
    """On a phone the builder panel is the whole window but its margin, and its "Things to ask" end inside it.

    A layout guard, at 844 and at 664 (Safari's height with its bars). It was written for F1163, a misread of a shot
    (the composer's border taken for the card's edge); it passed on the code then, so F1163 was closed as no bug.
    """
    bad, said = [], []
    for size in ((390, 844), (390, 664)):
        ctx, page = await _assistant_page(browser, path="agents", width=size)
        try:
            await page.locator('[data-testid="assistant-open"]:visible').first.click()
            await page.locator('[data-testid="assistant-panel"] ul[aria-label="Things to ask"]').first.wait_for(timeout=10_000)
            await asyncio.sleep(0.8)
            m = await page.evaluate(PHONE_PANEL)
        finally:
            await ctx.close()
        at = f"{size[0]}x{size[1]}"
        if not m or not m["panel"] or not m["list"]:
            bad.append(f"{at}: no panel or no Things to ask ({m})")
            continue
        if m["panel"]["bottom"] < m["vh"] - 13:
            bad.append(f"{at}: the panel ends at {m['panel']['bottom']} of {m['vh']} ({m['style']})")
        if m["list"]["bottom"] > m["panel"]["bottom"]:
            bad.append(f"{at}: Things to ask end at {m['list']['bottom']}, below the panel's {m['panel']['bottom']}")
        if not m["cornerInPanel"]:
            bad.append(f"{at}: the bottom corner shows the page ({m['corner']})")
        said.append(f"{at} panel {m['panel']['top']}–{m['panel']['bottom']}, chips to {m['list']['bottom']}")
    if bad:
        raise AssertionError("; ".join(bad))
    return "; ".join(said)


