    oid = f"orch_uismoke_ask_{int(time.time())}"
    api("/api/orchestrations", "POST", judged_question_orchestration(oid))
    ctx = await browser.new_context(viewport={"width": WIDE[0], "height": WIDE[1]})
    page = await ctx.new_page()
